const parentItems = $('Parse NVD Response').all();
const epssItems = $input.all();

// Construir mapa cve_id → respuesta EPSS
const epssMap = {};
for (const item of epssItems) {
    const cveId = item.json?.data?.[0]?.cve;
    if (cveId) epssMap[cveId] = item.json;
}

// Join robusto por cve_id
const merged = [];
for (const parentItem of parentItems) {
    const parentData = parentItem.json;
    if (!parentData) continue;
    merged.push({
        json: {
            ...parentData,
            epss_raw: epssMap[parentData.cve_id] || {}
        }
    });
}

return merged;

const items = $input.all();
const output = [];

for (const item of items) {
    const data = item.json;
    if (!data) continue;

    // 1. Normalización de variables (escala estricta 0.0 a 1.0)
    const cvssNorm = (typeof data.cvss_score === 'number' ? data.cvss_score : 0.0) / 10.0;

    const rawEpssString = data.epss_raw?.data?.[0]?.epss;
    const epssScore = parseFloat(rawEpssString) || 0.0;

    const kevScore = data.cisa_kev ? 1.0 : 0.0;
    const critNorm = typeof data.crit_norm === 'number' ? data.crit_norm : parseFloat(data.crit_norm) || 0.0;
    const expScore = data.exposicion_internet ? 1.0 : 0.0;

    // 2. Fórmula canónica (R7: NO se modifica, SSVC solo se persiste)
    // IRC = (0.15 × CVSS) + (0.25 × EPSS) + (0.30 × KEV) + (0.20 × CRIT) + (0.10 × EXP)
    const rawIrc = (0.15 * cvssNorm) +
                   (0.25 * epssScore) +
                   (0.30 * kevScore) +
                   (0.20 * critNorm) +
                   (0.10 * expScore);

    const ircFinal = parseFloat(rawIrc.toFixed(4));

    // 3. Umbrales de prioridad
    let prioridadAsignada = 'INFORMATIVA';
    if (ircFinal >= 0.70) {
        prioridadAsignada = 'CRITICA';
    } else if (ircFinal >= 0.40) {
        prioridadAsignada = 'ALTA';
    }

    // 4. Aplanamiento 1:1 contra public.telemetria_vulnerabilidades
    output.push({
        json: {
            activo_id: data.activo_id,
            cve_id: data.cve_id,
            cvss_score: data.cvss_score,
            epss_score: epssScore,
            kev_status: data.cisa_kev,
            irc_score: ircFinal,
            prioridad: prioridadAsignada,
            fecha_publicacion_nvd: data.fecha_publicacion,

            // R6: la marca viene de Parse NVD Response, NO se regenera acá
            fecha_ingesta_pipeline: data.fecha_ingesta_pipeline,

            // Columnas nuevas (R3 y R6/R7)
            fecha_modificacion_nvd: data.fecha_modificacion_nvd,
            fuente_correlacion: data.fuente_correlacion,
            nivel_confianza: data.nivel_confianza,
            ssvc_exploitation: data.ssvc_exploitation,

            cve_description: data.cve_description,
            nvd_url: `https://nvd.nist.gov/vuln/detail/${data.cve_id}`,
            epss_url: `https://api.first.org/data/v1/epss?cve=${data.cve_id}`
        }
    });
}

return output;

const webhook  = $('Webhook Trigger').item.json.body;
const asset    = $('Fetch Asset DB').item.json;
const nvd      = $('Query NVD').item.json;
const epssRaw  = $input.item.json?.data?.[0]?.epss;

const vuln     = nvd.vulnerabilities?.[0]?.cve;
const cvssScore = vuln?.metrics?.cvssMetricV31?.[0]?.cvssData?.baseScore
               ?? vuln?.metrics?.cvssMetricV30?.[0]?.cvssData?.baseScore
               ?? vuln?.metrics?.cvssMetricV40?.[0]?.cvssData?.baseScore
               ?? vuln?.metrics?.cvssMetricV2?.[0]?.cvssData?.baseScore
               ?? 0;
const kevStatus = Boolean(vuln?.cisaExploitAdd);

const cvssNorm  = cvssScore / 10.0;
const epssScore = parseFloat(epssRaw) || 0.0;
const kevScore  = kevStatus ? 1.0 : 0.0;
const critNorm  = parseFloat(asset.crit_norm) || 0.0;
const expScore  = asset.exposicion_internet ? 1.0 : 0.0;

const rawIrc = (0.15 * cvssNorm) + (0.25 * epssScore) +
               (0.30 * kevScore) + (0.20 * critNorm)  + (0.10 * expScore);
const ircFinal = parseFloat(rawIrc.toFixed(4));

let prioridad = 'INFORMATIVA';
if (ircFinal >= 0.70)      prioridad = 'CRITICA';
else if (ircFinal >= 0.40) prioridad = 'ALTA';

return [{
  json: {
    activo_id:              asset.activo_id,
    cve_id:                 webhook.cve_id,
    hostname:               asset.hostname,
    exposicion_internet:    asset.exposicion_internet,
    crit_norm:              critNorm,
    cvss_score:             cvssScore,
    epss_score:             epssScore,
    kev_status:             kevStatus,
    irc_score:              ircFinal,
    prioridad,
    fecha_publicacion_nvd:  vuln?.published ?? null,
    fecha_ingesta_pipeline: new Date().toISOString(),
    cve_description:        vuln?.descriptions?.find(d => d.lang === 'en')?.value ?? '',
    nvd_url:                `https://nvd.nist.gov/vuln/detail/${webhook.cve_id}`,
    epss_url:               `https://api.first.org/data/v1/epss?cve=${webhook.cve_id}`
  }
}];

// ============================================================
// Parse NVD Response — correlación delta-driven (R2 + R3)
// Entrada: 1 o más ítems (páginas) de la NVD + 30 activos
// Salida:   1 ítem por cada par CVE-activo que correlaciona
// ============================================================

const assets = $('Fetch Assets').all().map(i => i.json);
const paginas = $input.all().map(i => i.json);
const vulnerabilities = paginas.flatMap(p => p?.vulnerabilities || []);

// Marca de ingesta única para toda la corrida (R6 / T1).
// Va acá y no en Calculate IRC: mide desde que el CVE entra.
const FECHA_INGESTA = new Date().toISOString();

// ---------- utilidades portadas de correlacion_cascada.py ----------

function normalizar(texto) {
  return String(texto || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

function palabras(...campos) {
  return campos.join('_').toLowerCase()
    .split(/[_\-.\s]+/)
    .filter(t => t && t !== '*')
    .sort()
    .join('|');
}

function clavesCpe(cpeString) {
  const p = String(cpeString || '').split(':');
  if (p.length < 2) return [];
  let vendor, product, version;
  if (p[1] === '2.3') {
    if (p.length < 5) return [];
    vendor = p[3]; product = p[4]; version = p.length > 5 ? p[5] : '*';
  } else if (p[1].startsWith('/')) {
    if (p.length < 4) return [];
    vendor = p[2]; product = p[3]; version = p.length > 4 ? p[4] : '*';
  } else {
    return [];
  }
  return [palabras(vendor, product), palabras(vendor, product, version)];
}

function parsearCpe(cpeString) {
  const p = String(cpeString || '').split(':');
  if (p.length < 2) return ['', ''];
  if (p[1] === '2.3' && p.length >= 5) return [p[3], p[4]];
  if (p[1].startsWith('/') && p.length >= 4) return [p[2], p[3]];
  return ['', ''];
}

// ---------- precálculo de los 30 activos ----------

const objetivos = assets.map(a => {
  const [v, pr] = parsearCpe(a.cpe);
  return {
    activo_id: a.activo_id,
    hostname: a.hostname,
    exposicion_internet: a.exposicion_internet,
    crit_norm: parseFloat(a.crit_norm),
    claves: clavesCpe(a.cpe),
    vendorNorm: normalizar(v),
    productNorm: normalizar(pr)
  };
});

// ---------- recorrido de los CVE ----------

const salida = [];

for (const entrada of vulnerabilities) {
  const cve = entrada?.cve;
  if (!cve?.id) continue;

  // --- CVSS: v3.1 -> v3.0 -> v4.0 -> v2 ---
  let baseScore = 0.0;
  let severity = 'UNKNOWN';
  const m = cve.metrics || {};
  if (m.cvssMetricV31?.[0]?.cvssData?.baseScore !== undefined) {
    baseScore = m.cvssMetricV31[0].cvssData.baseScore;
    severity = m.cvssMetricV31[0].cvssData.baseSeverity;
  } else if (m.cvssMetricV30?.[0]?.cvssData?.baseScore !== undefined) {
    baseScore = m.cvssMetricV30[0].cvssData.baseScore;
    severity = m.cvssMetricV30[0].cvssData.baseSeverity;
  } else if (m.cvssMetricV40?.[0]?.cvssData?.baseScore !== undefined) {
    baseScore = m.cvssMetricV40[0].cvssData.baseScore;
    severity = m.cvssMetricV40[0].cvssData.baseSeverity;
  } else if (m.cvssMetricV2?.[0]?.cvssData?.baseScore !== undefined) {
    baseScore = m.cvssMetricV2[0].cvssData.baseScore;
    severity = m.cvssMetricV2[0].baseSeverity || 'MEDIUM';
  }

  // --- KEV (R8: ya venía, no se consulta a CISA) ---
  const isKev = Boolean(cve.cisaExploitAdd);

  // --- SSVC exploitation (R7: solo se persiste, no entra al IRC) ---
  let ssvcExploitation = null;
  const opciones = cve.metrics?.ssvcV203?.[0]?.ssvcData?.options || [];
  for (const o of opciones) {
    if (o && o.exploitation !== undefined) { ssvcExploitation = o.exploitation; break; }
  }

  // --- descripción en inglés ---
  let desc = 'Sin descripción en NVD';
  if (Array.isArray(cve.descriptions)) {
    const en = cve.descriptions.find(d => d.lang === 'en');
    if (en) desc = en.value;
  }

  // --- N1: CPE del NIST (configurations). Casi siempre ausente en delta. ---
  const clavesN1 = new Set();
  for (const bloque of (cve.configurations || [])) {
    for (const nodo of (bloque.nodes || [])) {
      for (const match of (nodo.cpeMatch || [])) {
        if (match.criteria) clavesCpe(match.criteria).forEach(k => clavesN1.add(k));
      }
    }
  }

  // --- N4: vendor/product en texto libre del fabricante (affected) ---
  const textosN4 = [];
  for (const bloque of (cve.affected || [])) {
    for (const dato of (bloque.affectedData || [])) {
      const v = normalizar(dato.vendor);
      const p = normalizar(dato.product);
      if (v && p) textosN4.push([v, p]);
    }
  }

  // --- comparación contra cada activo ---
  for (const obj of objetivos) {
    let fuente = null;
    let confianza = null;

    if (obj.claves.some(k => clavesN1.has(k))) {
      fuente = 'NVD';
      confianza = 'FORMAL';
    } else {
      for (const [vTxt, pTxt] of textosN4) {
        // Validación para prevenir falsos positivos por subcadenas muy cortas
        if (vTxt.length < 4 || pTxt.length < 3) continue;

        const okV = obj.vendorNorm && (obj.vendorNorm.includes(vTxt) || vTxt.includes(obj.vendorNorm));
        const okP = obj.productNorm && (obj.productNorm.includes(pTxt) || pTxt.includes(obj.productNorm));
        if (okV && okP) { fuente = 'HEURISTICA'; confianza = 'INFERIDA'; break; }
      }
    }

    if (!fuente) continue;

    salida.push({
      json: {
        activo_id: obj.activo_id,
        hostname: obj.hostname,
        exposicion_internet: obj.exposicion_internet,
        crit_norm: obj.crit_norm,

        cve_id: cve.id,
        cvss_score: baseScore,
        cvss_severity: severity,
        cisa_kev: isKev,
        cve_description: desc,
        fecha_publicacion: cve.published,

        fecha_ingesta_pipeline: FECHA_INGESTA,
        fecha_modificacion_nvd: cve.lastModified || null,
        fuente_correlacion: fuente,
        nivel_confianza: confianza,
        ssvc_exploitation: ssvcExploitation
      }
    });
  }
}

return salida;

const paginas = $('Fetch CVEs').all().map(i => i.json);
const cveIngeridos = paginas[0]?.totalResults ?? 0;
const cveRecibidos = paginas.flatMap(p => p?.vulnerabilities || []).length;
const truncado = cveIngeridos > cveRecibidos;

let pares = [];
try {
  pares = $('Parse NVD Response').all().map(i => i.json);
} catch (e) {
  pares = [];
}

const porFuente = {
  NVD: new Set(), CNA: new Set(), ADP: new Set(), HEURISTICA: new Set()
};
const idsUnicos = new Set();

for (const p of pares) {
  if (!p?.cve_id) continue;
  idsUnicos.add(p.cve_id);
  if (porFuente[p.fuente_correlacion]) porFuente[p.fuente_correlacion].add(p.cve_id);
}

const metadata = {
  cve_ingeridos: cveIngeridos,
  correlacionados: idsUnicos.size,
  pares: pares.length,
  n1: porFuente.NVD.size,
  n2: porFuente.CNA.size,
  n3: porFuente.ADP.size,
  n4: porFuente.HEURISTICA.size,
  ids: Array.from(idsUnicos).sort(),
  recibidos: cveRecibidos,
  truncado: truncado,
  paginas_recibidas: paginas.length
};

return [{
  json: {
    entidad_id: Number($execution.id) || 0,
    metadata_str: JSON.stringify(metadata)
  }
}];
